{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "A closely related tropane ester PET tracer showed fast brain entry and high striatal uptake (3.23% ID/g) in rats, demonstrating efficient BBB passage for the tropane-ester scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Benztropine-like tropane tertiary amines readily and rapidly cross the BBB with brain-to-plasma ratios at least 2-fold higher than cocaine, supporting meaningful CNS access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A tropane-based PET ligand in humans rapidly entered the brain and distributed to receptor-rich regions, providing direct human evidence that tropane amines can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "N-methylpiperidine/tropane acetate and propionate esters showed rapid and high brain uptake (~10% dose/g) in mice, directly supporting CNS penetration of ester-containing basic amines despite ionization concerns.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Diphenhydramine, a basic tertiary amine with similar ionization and lipophilicity liabilities, exhibits active net uptake across the BBB with Kp,uu values well above 1 and high human brain H1 receptor occupancy, showing that such compounds can have meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer experimental records from closely related tropane esters, tropane amines, and basic tertiary amines demonstrate rapid and meaningful BBB penetration in rodents and humans. These direct in vivo data override the physicochemical prior suggesting low passive permeability, and support a pass for meaningful CNS access.",
  "evidence_gaps": [
    "No direct Kp,uu or CSF measurement is available for the exact query molecule.",
    "The ester group may be hydrolyzed in vivo, so the permeating species could differ from the intact molecule.",
    "Exact enantiomer-specific brain exposure data are not available, though racemic atropine is known to produce central antimuscarinic effects."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

